UPDATE companies SET description = 'Компания в Москве поставляет различные виды упаковочных материалов со склада на Новоалексеевской улице. В наличии представлены полиэтиленовые пакеты, стрейч-плёнка и упаковочный скотч. Ассортимент также включает бумажную продукцию: обычные пакеты, варианты с zip-замком и подарочную упаковку. Для защиты товаров в каталоге значатся воздушно-пузырчатая плёнка и различные наполнители. Работа ведётся только с юридическими лицами.', updated_at = now() WHERE slug = 'asd';
