UPDATE companies SET description = 'В перечне представлены упаковочные материалы, включая бумажные пакеты с замком zip-lock и без, изделия из воздушно-пузырчатой плёнки, полиэтиленовые пакеты и скотч. Также доступны картонная упаковка, различные наполнители и паллеты для хранения и транспортировки. Поставщик оказывает полиграфические услуги, а также предоставляет услуги по фасовке и упаковке товаров. Основные позиции, такие как zip-lock пакеты и бумажная упаковка, находятся в наличии.', updated_at = now() WHERE slug = 'andipack';
